from operator import length_hint
from itertools import permutations
from collections.abc import Sequence
from functools import partial

from cons import cons
from cons.core import ConsNull, ConsPair
from unification import reify, var
from unification.core import isground

from .core import (
    eq,
    conde,
    lany,
    lall,
)


def heado(head, coll):
    """Construct a goal stating that head is the head of coll."""
    return eq(cons(head, var()), coll)


def tailo(tail, coll):
    """Construct a goal stating that tail is the tail of coll."""
    return eq(cons(var(), tail), coll)


def conso(h, t, l):
    """Construct a goal stating that cons h + t == l."""
    return eq(cons(h, t), l)


def nullo(*args, refs=None, default_ConsNull=list):
    """Create a goal asserting that one or more terms are a/the same `ConsNull` type."""
    def nullo_goal(s):
        nonlocal args, default_ConsNull

        if refs is not None:
            refs_rf = reify(refs, s)
        else:
            refs_rf = ()

        args_rf = reify(args, s)

        arg_null_types = set(
            type(a)
            for a in args_rf + refs_rf
            if isinstance(a, (ConsPair, ConsNull)) and not issubclass(type(a), ConsPair)
        )

        try:
            null_type = arg_null_types.pop()
        except KeyError:
            null_type = default_ConsNull

        if len(arg_null_types) > 0 and any(a != null_type for a in arg_null_types):
            return

        g = lall(*[eq(a, null_type()) for a in args_rf])

        yield from g(s)

    return nullo_goal


def itero(l, nullo_refs=None, default_ConsNull=list):
    """Construct a goal asserting that a term is an iterable type."""
    def itero_goal(S):
        nonlocal l, nullo_refs, default_ConsNull
        l_rf = reify(l, S)
        c, d = var(), var()
        g = conde(
            [nullo(l_rf, refs=nullo_refs, default_ConsNull=default_ConsNull)],
            [conso(c, d, l_rf), itero(d, default_ConsNull=default_ConsNull)],
        )
        yield from g(S)

    return itero_goal


def membero(x, ls):
    """Construct a goal stating that x is an item of coll."""
    def membero_goal(S):
        nonlocal x, ls

        x_rf, ls_rf = reify((x, ls), S)
        a, d = var(), var()

        g = lall(conso(a, d, ls), conde([eq(a, x)], [membero(x, d)]))

        yield from g(S)

    return membero_goal


def appendo(l, s, out, default_ConsNull=list):
    """Construct a goal for the relation l + s = ls."""
    def appendo_goal(S):
        nonlocal l, s, out

        l_rf, s_rf, out_rf = reify((l, s, out), S)

        a, d, res = var(), var(), var()

        _nullo = partial(nullo, default_ConsNull=default_ConsNull)

        g = conde(
            [_nullo(s_rf, l_rf, out_rf)],  # All empty
            [conso(a, d, out_rf), eq(s_rf, out_rf), _nullo(l_rf)],  # l is empty
            [conso(a, d, l_rf), conso(a, res, out_rf), appendo(d, s_rf, res)],  # Recursion
        )

        yield from g(S)

    return appendo_goal


def rembero(x, l, o, default_ConsNull=list):
    """Remove the first occurrence of `x` in `l`, resulting in `o`."""
    from .constraints import neq

    def rembero_goal(S):
        nonlocal x, l, o

        x_rf, l_rf, o_rf = reify((x, l, o), S)

        l_car, l_cdr, r = var(), var(), var()

        g = conde(
            [nullo(l_rf, o_rf, default_ConsNull=default_ConsNull)],  # Empty list case
            [conso(l_car, l_cdr, l_rf), eq(x_rf, l_car), eq(l_cdr, o_rf)],  # Remove first match
            [
                conso(l_car, l_cdr, l_rf),
                neq(l_car, x),
                conso(l_car, r, o_rf),
                rembero(x_rf, l_cdr, r, default_ConsNull=default_ConsNull),  # Recursive step
            ],
        )

        yield from g(S)

    return rembero_goal


def permuteo(a, b, inner_eq=eq, default_ConsNull=list, no_ident=False):
    """Construct a goal asserting equality or sequences under permutation."""
    def permuteo_goal(S):
        nonlocal a, b, inner_eq, no_ident

        a_rf, b_rf = reify((a, b), S)

        if no_ident and isground(a_rf, S) and isground(b_rf, S) and a_rf == b_rf:
            return

        a_len = length_hint(a_rf, -1)
        b_len = length_hint(b_rf, -1)
        if a_len > 0 and b_len > 0 and a_len != b_len:
            return

        if isinstance(a_rf, Sequence):
            if isinstance(b_rf, Sequence):
                if no_ident and isground(a_rf, S) and tuple(a_rf) == tuple(b_rf):
                    return

                a_perms = permutations(a_rf)
                if no_ident:
                    a_perms = (p for p in a_perms if tuple(p) != tuple(b_rf))

                yield from lany(inner_eq(b_rf, type(a_rf)(p)) for p in a_perms)(S)

            else:
                yield from conde([permuteo(a_rf, b, inner_eq, default_ConsNull, no_ident)])(S)

        elif isinstance(b_rf, Sequence):
            b_perms = permutations(b_rf)
            if no_ident:
                b_perms = (p for p in b_perms if tuple(p) != tuple(a_rf))

            yield from lany(inner_eq(a_rf, type(b_rf)(p)) for p in b_perms)(S)

        else:
            yield from conde(
                [permuteo(a_rf, b_rf, inner_eq, default_ConsNull, no_ident)]
            )(S)

    return permuteo_goal


# For backward compatibility
permuteq = permuteo
